    "term": "Z-검정(Z-test)",
    "summary": "모분산을 알거나 표본이 충분히 클 때, 표준화한 통계량이 표준정규분포를 따른다는 성질을 이용해 모평균이나 모비율에 관한 가설을 검정하는 방법.",
